contracts/SybilNet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

interface IZKVerifier {
    function verifyHumanityProof(
        uint[2] memory pA,
        uint[2][2] memory pB,
        uint[2] memory pC,
        uint[4] memory pubSignals
    ) external returns (bool);
}

/**
 * @title  SybilNet
 * @author Sybil-Net Project
 * @notice Decentralised identity protocol where wallets stake ETH to mint a
 *         "Humanity Credential".  A trusted GNN oracle continuously monitors
 *         the on-chain transaction graph.  If a wallet is flagged as a Sybil
 *         attacker, the oracle calls `slash()` which destroys the stake and
 *         burns the credential.
 *
 * ┌─────────────────────────────────────────────────────────────────────────┐
 * │  User Stakes ETH ──► Credential Minted ──► GNN monitors topology       │
 * │         ▲                                         │                    │
 * │         │                    Sybil detected?      │                    │
 * │         │                         ├── Yes ────► Slash + Burn           │
 * │         │                         └── No  ────► Credential stays valid │
 * │  Credential enables:                                                    │
 * │    • Undercollateralised DeFi loans (Credit Hub)                       │
 * │    • Verified NFT marketplace access (Asset Exchange)                  │
 * │    • Protected yield farming (Yield Hub)                               │
 * └─────────────────────────────────────────────────────────────────────────┘
 *
 * Roles:
 *   DEFAULT_ADMIN_ROLE — protocol admin (multisig in production)
 *   ORACLE_ROLE        — GNN backend; may call slash() and reportSuspicious()
 *   GUARDIAN_ROLE      — emergency pause only
 */
contract SybilNet is AccessControl, ReentrancyGuard, Pausable {

    // ─── Roles ────────────────────────────────────────────────────────────
    bytes32 public constant ORACLE_ROLE   = keccak256("ORACLE_ROLE");
    bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");

    // ─── Configuration ────────────────────────────────────────────────────
    /// Minimum stake required to mint a Humanity Credential (0.01 ETH)
    uint256 public minStake = 0.01 ether;

    /// Duration after slashing during which the wallet is permanently banned
    uint256 public constant BAN_DURATION = 365 days;

    /// Share of slashed stake sent to the slash reporter (in basis points, e.g. 1000 = 10%)
    uint256 public slashReporterFeeBps = 1000;

    /// Treasury address — receives the remainder of slashed funds
    address payable public treasury;

    // ─── Credential state ─────────────────────────────────────────────────
    enum CredentialStatus { None, Active, Suspended, Revoked }

    struct Credential {
        CredentialStatus status;
        uint256          stakedAmount;   // ETH locked by this wallet
        uint256          issuedAt;       // block.timestamp of minting
        uint256          sybilScore;     // 0–100; updated by oracle (100 = definite Sybil)
        uint256          slashedAt;      // timestamp of slash event (0 if not slashed)
        uint256          warnCount;      // number of oracle warnings before slash
    }

    /// wallet address → credential
    mapping(address => Credential) public credentials;

    /// Total ETH currently staked in the protocol
    uint256 public totalStaked;

    /// Total ETH slashed since deployment
    uint256 public totalSlashed;

    /// ZK Verifier contract address
    address public zkVerifier;

    // ─── Events ───────────────────────────────────────────────────────────
    event CredentialMinted(address indexed wallet, uint256 stakedAmount, uint256 timestamp);
    event CredentialRevoked(address indexed wallet, string reason);
    event SybilWarning(address indexed wallet, uint256 newScore, uint256 warnCount);
    event WalletSlashed(address indexed wallet, uint256 slashedAmount, uint256 reporterFee, address indexed reporter);
    event StakeWithdrawn(address indexed wallet, uint256 amount);
    event OracleScoreUpdated(address indexed wallet, uint256 oldScore, uint256 newScore);
    event MinStakeUpdated(uint256 oldMin, uint256 newMin);
    event TreasuryUpdated(address oldTreasury, address newTreasury);
    event AnonymousCredentialVerified(bytes32 nullifier, uint256 timestamp);

    // ─── Errors ───────────────────────────────────────────────────────────
    error InsufficientStake(uint256 sent, uint256 required);
    error CredentialAlreadyActive();
    error NoActiveCredential();
    error WalletBanned(address wallet, uint256 bannedUntil);
    error ScoreOutOfRange(uint256 score);
    error NothingToWithdraw();
    error WithdrawalLocked();
    error TransferFailed();
    error InvalidAddress();
    error InvalidBps(uint256 bps);
    error InvalidZKProof();

    // ─── Modifiers ────────────────────────────────────────────────────────
    modifier hasActiveCredential(address wallet) {
        if (credentials[wallet].status != CredentialStatus.Active) {
            revert NoActiveCredential();
        }
        _;
    }

    modifier notBanned(address wallet) {
        Credential storage c = credentials[wallet];
        if (c.status == CredentialStatus.Revoked) {
            uint256 bannedUntil = c.slashedAt + BAN_DURATION;
            if (block.timestamp < bannedUntil) {
                revert WalletBanned(wallet, bannedUntil);
            }
        }
        _;
    }

    // ─── Constructor ──────────────────────────────────────────────────────
    constructor(address _treasury) {
        if (_treasury == address(0)) revert InvalidAddress();
        treasury = payable(_treasury);

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(GUARDIAN_ROLE,      msg.sender);
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  USER FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Stake ETH and mint a Humanity Credential for the caller.
     * @dev    Caller must send at least `minStake` wei.
     *         Re-staking is allowed after a ban has expired.
     */
    function mintCredential()
        external
        payable
        nonReentrant
        whenNotPaused
        notBanned(msg.sender)
    {
        if (msg.value < minStake) {
            revert InsufficientStake(msg.value, minStake);
        }
        if (credentials[msg.sender].status == CredentialStatus.Active) {
            revert CredentialAlreadyActive();
        }

        credentials[msg.sender] = Credential({
            status:       CredentialStatus.Active,
            stakedAmount: msg.value,
            issuedAt:     block.timestamp,
            sybilScore:   0,
            slashedAt:    0,
            warnCount:    0
        });

        totalStaked += msg.value;

        emit CredentialMinted(msg.sender, msg.value, block.timestamp);
    }

    /**
     * @notice Voluntarily withdraw stake and surrender the Humanity Credential.
     * @dev    Not callable while the credential is Suspended (pending slash review).
     */
    function withdrawStake()
        external
        nonReentrant
        whenNotPaused
        hasActiveCredential(msg.sender)
    {
        Credential storage c = credentials[msg.sender];
        uint256 amount = c.stakedAmount;

        if (amount == 0) revert NothingToWithdraw();

        c.status       = CredentialStatus.Revoked;
        c.stakedAmount = 0;
        totalStaked   -= amount;

        emit StakeWithdrawn(msg.sender, amount);
        emit CredentialRevoked(msg.sender, "voluntary_withdrawal");

        (bool ok, ) = payable(msg.sender).call{value: amount}("");
        if (!ok) revert TransferFailed();
    }

    /**
     * @notice Verify a zk-SNARK proof of humanity without revealing the wallet.
     * @dev    Calls the ZKVerifier contract. Reverts if proof is invalid or reused.
     */
    function verifyAnonymous(
        uint[2] memory pA,
        uint[2][2] memory pB,
        uint[2] memory pC,
        uint[4] memory pubSignals
    ) external whenNotPaused {
        if (zkVerifier == address(0)) revert InvalidAddress();

        bool isValid = IZKVerifier(zkVerifier).verifyHumanityProof(pA, pB, pC, pubSignals);
        if (!isValid) revert InvalidZKProof();

        bytes32 nullifier = keccak256(abi.encodePacked(pA, pB, pC, pubSignals));
        emit AnonymousCredentialVerified(nullifier, block.timestamp);
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  ORACLE FUNCTIONS  (called by the GNN backend)
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Update the Sybil score for a wallet based on the latest GNN output.
     * @param  wallet    The wallet address to update.
     * @param  newScore  New Sybil probability score, 0–100.
     *                   • 0–29  : considered clean
     *                   • 30–69 : warning zone
     *                   • 70–100: high-risk, triggers suspension
     */
    function updateSybilScore(address wallet, uint256 newScore)
        external
        onlyRole(ORACLE_ROLE)
        whenNotPaused
        hasActiveCredential(wallet)
    {
        if (newScore > 100) revert ScoreOutOfRange(newScore);

        Credential storage c = credentials[wallet];
        uint256 oldScore = c.sybilScore;
        c.sybilScore = newScore;

        emit OracleScoreUpdated(wallet, oldScore, newScore);

        // Auto-suspend if score crosses the high-risk threshold
        if (newScore >= 70 && c.status == CredentialStatus.Active) {
            c.status = CredentialStatus.Suspended;
            c.warnCount += 1;
            emit SybilWarning(wallet, newScore, c.warnCount);
        }
    }

    /**
     * @notice Slash a wallet identified as a Sybil attacker by the GNN oracle.
     *         Destroys their staked ETH (split: reporter fee + treasury).
     *         Burns the Humanity Credential and bans the wallet for BAN_DURATION.
     *
     * @param  wallet    The Sybil wallet to slash.
     * @param  reporter  Address that receives the slash reporter fee (could be
     *                   the oracle itself or a human whistleblower).
     */
    function slash(address wallet, address payable reporter)
        external
        nonReentrant
        onlyRole(ORACLE_ROLE)
        whenNotPaused
    {
        if (reporter == address(0)) revert InvalidAddress();

        Credential storage c = credentials[wallet];

        // Allow slashing of both Active and Suspended credentials
        require(
            c.status == CredentialStatus.Active ||
            c.status == CredentialStatus.Suspended,
            "SybilNet: wallet not slashable"
        );

        uint256 slashAmount = c.stakedAmount;

        // Update state BEFORE transfers (CEI pattern)
        c.status       = CredentialStatus.Revoked;
        c.stakedAmount = 0;
        c.slashedAt    = block.timestamp;
        totalStaked   -= slashAmount;
        totalSlashed  += slashAmount;

        emit WalletSlashed(wallet, slashAmount, 0, reporter);
        emit CredentialRevoked(wallet, "gnn_sybil_detection");

        // ── Distribute slashed funds ─────────────────────────────────────
        uint256 reporterFee = (slashAmount * slashReporterFeeBps) / 10_000;
        uint256 treasuryAmt = slashAmount - reporterFee;

        if (reporterFee > 0) {
            (bool ok1, ) = reporter.call{value: reporterFee}("");
            if (!ok1) revert TransferFailed();
        }
        if (treasuryAmt > 0) {
            (bool ok2, ) = treasury.call{value: treasuryAmt}("");
            if (!ok2) revert TransferFailed();
        }
    }

    /**
     * @notice Batch-slash multiple Sybil wallets in a single tx (gas efficient
     *         for large bot rings identified by the GNN).
     */
    function batchSlash(address[] calldata wallets, address payable reporter)
        external
        nonReentrant
        onlyRole(ORACLE_ROLE)
        whenNotPaused
    {
        if (reporter == address(0)) revert InvalidAddress();

        uint256 totalSlashBatch = 0;

        for (uint256 i = 0; i < wallets.length; i++) {
            Credential storage c = credentials[wallets[i]];
            if (
                c.status != CredentialStatus.Active &&
                c.status != CredentialStatus.Suspended
            ) continue;

            uint256 amt = c.stakedAmount;
            c.status       = CredentialStatus.Revoked;
            c.stakedAmount = 0;
            c.slashedAt    = block.timestamp;
            totalStaked   -= amt;
            totalSlashed  += amt;
            totalSlashBatch += amt;

            emit WalletSlashed(wallets[i], amt, 0, reporter);
            emit CredentialRevoked(wallets[i], "gnn_batch_slash");
        }

        // Single distribution for the whole batch
        uint256 reporterFee = (totalSlashBatch * slashReporterFeeBps) / 10_000;
        uint256 treasuryAmt = totalSlashBatch - reporterFee;

        if (reporterFee > 0) {
            (bool ok1, ) = reporter.call{value: reporterFee}("");
            if (!ok1) revert TransferFailed();
        }
        if (treasuryAmt > 0) {
            (bool ok2, ) = treasury.call{value: treasuryAmt}("");
            if (!ok2) revert TransferFailed();
        }
    }

    /**
     * @notice Lift a Suspension if the oracle re-evaluates a wallet as clean.
     */
    function liftSuspension(address wallet)
        external
        onlyRole(ORACLE_ROLE)
        whenNotPaused
    {
        Credential storage c = credentials[wallet];
        require(c.status == CredentialStatus.Suspended, "SybilNet: not suspended");
        c.status     = CredentialStatus.Active;
        c.sybilScore = 0;
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  ADMIN FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════

    function setMinStake(uint256 newMin) external onlyRole(DEFAULT_ADMIN_ROLE) {
        emit MinStakeUpdated(minStake, newMin);
        minStake = newMin;
    }

    function setTreasury(address payable newTreasury)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        if (newTreasury == address(0)) revert InvalidAddress();
        emit TreasuryUpdated(treasury, newTreasury);
        treasury = newTreasury;
    }

    function setSlashReporterFee(uint256 newBps)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        if (newBps > 3000) revert InvalidBps(newBps); // cap at 30%
        slashReporterFeeBps = newBps;
    }

    function setZKVerifier(address _zkVerifier)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        if (_zkVerifier == address(0)) revert InvalidAddress();
        zkVerifier = _zkVerifier;
    }

    function pause()   external onlyRole(GUARDIAN_ROLE) { _pause(); }
    function unpause() external onlyRole(GUARDIAN_ROLE) { _unpause(); }

    // ═══════════════════════════════════════════════════════════════════════
    //  VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Returns true only if the wallet holds a currently Active credential.
    function isVerifiedHuman(address wallet) external view returns (bool) {
        return credentials[wallet].status == CredentialStatus.Active;
    }

    /// @notice Returns the current Sybil risk score (0–100) for a wallet.
    function getSybilScore(address wallet) external view returns (uint256) {
        return credentials[wallet].sybilScore;
    }

    /// @notice Returns the full credential struct for a wallet.
    function getCredential(address wallet)
        external
        view
        returns (Credential memory)
    {
        return credentials[wallet];
    }
}

contracts/SybilNetBridge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title  ISybilNet
 * @notice Interface to read credential state from the core SybilNet contract.
 */
interface ISybilNet {
    enum CredentialStatus { None, Active, Suspended, Revoked }

    struct Credential {
        CredentialStatus status;
        uint256          stakedAmount;
        uint256          issuedAt;
        uint256          sybilScore;
        uint256          slashedAt;
        uint256          warnCount;
    }

    function isVerifiedHuman(address wallet) external view returns (bool);
    function getSybilScore(address wallet) external view returns (uint256);
    function getCredential(address wallet) external view returns (Credential memory);
}

/**
 * @title  SybilNetBridge
 * @author Sybil-Net Project
 * @notice Cross-Chain Credential Bridge (Week 7)
 *
 *         Enables Humanity Credentials from the core SybilNet contract to be
 *         portable across L2 chains (Polygon, Arbitrum, Base) using a
 *         Lock-and-Mint pattern:
 *
 *         Source chain:
 *           1. User calls lockCredential(destChainId)
 *           2. Contract verifies they hold an Active credential via ISybilNet
 *           3. Emits CredentialLocked event (picked up by the bridge relay)
 *
 *         Destination chain:
 *           1. Bridge operator calls mintBridgedCredential() with oracle signature
 *           2. Contract verifies the signature and mints a BridgedCredential
 *           3. isBridgedHuman() returns true for the wallet
 *
 * ┌─────────────────────────────────────────────────────────────────────────┐
 * │   Source Chain                              Destination Chain (L2)     │
 * │   ─────────────                             ──────────────────────     │
 * │   lockCredential(chainId)                                             │
 * │     └─► CredentialLocked event ──relay──► mintBridgedCredential()     │
 * │                                             └─► BridgedCredential    │
 * │   unlockCredential()                          isBridgedHuman() ✓     │
 * │     └─► CredentialUnlocked                                           │
 * │                                           revokeBridgedCredential() │
 * │                                             └─► credential removed  │
 * └─────────────────────────────────────────────────────────────────────────┘
 *
 * Roles:
 *   DEFAULT_ADMIN_ROLE    — protocol admin
 *   BRIDGE_OPERATOR_ROLE  — cross-chain relay service
 */
contract SybilNetBridge is AccessControl, ReentrancyGuard, Pausable {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    // ─── Roles ────────────────────────────────────────────────────────────
    bytes32 public constant BRIDGE_OPERATOR_ROLE = keccak256("BRIDGE_OPERATOR_ROLE");

    // ─── Core contract reference ──────────────────────────────────────────
    ISybilNet public sybilNet;

    // ─── Supported chains ─────────────────────────────────────────────────
    mapping(uint256 => string) public supportedChains;
    mapping(uint256 => bool)   public isChainSupported;

    // ─── Lock records (source chain side) ─────────────────────────────────
    struct LockRecord {
        address wallet;
        uint256 destChainId;
        uint256 sybilScore;
        uint256 stakedAmount;
        uint256 nonce;
        uint256 lockedAt;
        bool    isLocked;
    }

    mapping(address => LockRecord) public lockRecords;
    mapping(address => uint256)    public lockNonces;

    // ─── Bridged credentials (destination chain side) ─────────────────────
    struct BridgedCredential {
        address wallet;
        uint256 sybilScore;
        uint256 sourceStake;
        uint256 sourceChainId;
        uint256 bridgedAt;
        bool    isActive;
    }

    mapping(address => BridgedCredential) public bridgedCredentials;

    /// Total bridged credentials currently active
    uint256 public totalBridged;

    /// Oracle signer address — must match the signature in mintBridgedCredential
    address public oracleSigner;

    // ─── Events ───────────────────────────────────────────────────────────
    event CredentialLocked(
        address indexed wallet,
        uint256 destChainId,
        uint256 sybilScore,
        uint256 stakedAmount,
        uint256 nonce,
        uint256 timestamp
    );
    event CredentialUnlocked(address indexed wallet, uint256 timestamp);
    event BridgedCredentialMinted(
        address indexed wallet,
        uint256 sybilScore,
        uint256 sourceStake,
        uint256 sourceChainId,
        uint256 timestamp
    );
    event BridgedCredentialRevoked(address indexed wallet, string reason, uint256 timestamp);
    event ChainAdded(uint256 chainId, string name);
    event ChainRemoved(uint256 chainId);
    event OracleSignerUpdated(address oldSigner, address newSigner);

    // ─── Errors ───────────────────────────────────────────────────────────
    error NoActiveCredential();
    error AlreadyLocked();
    error NotLocked();
    error UnsupportedChain(uint256 chainId);
    error AlreadyBridged();
    error NotBridged();
    error InvalidSignature();
    error InvalidAddress();
    error InvalidNonce(uint256 expected, uint256 got);

    // ─── Constructor ──────────────────────────────────────────────────────
    constructor(address _sybilNet, address _oracleSigner) {
        if (_sybilNet == address(0) || _oracleSigner == address(0))
            revert InvalidAddress();

        sybilNet     = ISybilNet(_sybilNet);
        oracleSigner = _oracleSigner;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(BRIDGE_OPERATOR_ROLE, msg.sender);

        // Register default supported chains
        _addChain(137,   "Polygon");
        _addChain(42161, "Arbitrum");
        _addChain(8453,  "Base");
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  SOURCE CHAIN FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Lock your Humanity Credential for bridging to a destination chain.
     * @param  destChainId  The chain ID to bridge the credential to.
     */
    function lockCredential(uint256 destChainId)
        external
        whenNotPaused
    {
        if (!isChainSupported[destChainId])
            revert UnsupportedChain(destChainId);
        if (lockRecords[msg.sender].isLocked)
            revert AlreadyLocked();
        if (!sybilNet.isVerifiedHuman(msg.sender))
            revert NoActiveCredential();

        ISybilNet.Credential memory cred = sybilNet.getCredential(msg.sender);
        uint256 nonce = lockNonces[msg.sender]++;

        lockRecords[msg.sender] = LockRecord({
            wallet:       msg.sender,
            destChainId:  destChainId,
            sybilScore:   cred.sybilScore,
            stakedAmount: cred.stakedAmount,
            nonce:        nonce,
            lockedAt:     block.timestamp,
            isLocked:     true
        });

        emit CredentialLocked(
            msg.sender,
            destChainId,
            cred.sybilScore,
            cred.stakedAmount,
            nonce,
            block.timestamp
        );
    }

    /**
     * @notice Unlock a previously locked credential (cancel the bridge).
     */
    function unlockCredential() external whenNotPaused {
        if (!lockRecords[msg.sender].isLocked)
            revert NotLocked();

        lockRecords[msg.sender].isLocked = false;

        emit CredentialUnlocked(msg.sender, block.timestamp);
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  DESTINATION CHAIN FUNCTIONS (Bridge Operator)
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Mint a bridged credential on the destination chain.
     * @dev    Called by the BRIDGE_OPERATOR_ROLE after verifying the lock
     *         event on the source chain.
     *
     * @param  wallet         The wallet address receiving the bridged credential.
     * @param  sybilScore     The Sybil score from the source chain.
     * @param  sourceStake    The staked amount on the source chain.
     * @param  sourceChainId  The chain ID where the original credential lives.
     * @param  nonce          Lock nonce (must match source chain lock record).
     * @param  oracleSignature  EIP-191 signature from the oracle signer over
     *                          the message hash of (wallet, score, stake, chainId, nonce).
     */
    function mintBridgedCredential(
        address wallet,
        uint256 sybilScore,
        uint256 sourceStake,
        uint256 sourceChainId,
        uint256 nonce,
        bytes calldata oracleSignature
    )
        external
        onlyRole(BRIDGE_OPERATOR_ROLE)
        whenNotPaused
    {
        if (wallet == address(0)) revert InvalidAddress();
        if (bridgedCredentials[wallet].isActive) revert AlreadyBridged();

        // Verify oracle signature
        bytes32 messageHash = keccak256(abi.encodePacked(
            wallet, sybilScore, sourceStake, sourceChainId, nonce
        ));
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        address recovered = ethSignedHash.recover(oracleSignature);

        if (recovered != oracleSigner) revert InvalidSignature();

        bridgedCredentials[wallet] = BridgedCredential({
            wallet:        wallet,
            sybilScore:    sybilScore,
            sourceStake:   sourceStake,
            sourceChainId: sourceChainId,
            bridgedAt:     block.timestamp,
            isActive:      true
        });

        totalBridged++;

        emit BridgedCredentialMinted(
            wallet, sybilScore, sourceStake, sourceChainId, block.timestamp
        );
    }

    /**
     * @notice Revoke a bridged credential (e.g. if the source chain slashed).
     */
    function revokeBridgedCredential(address wallet, string calldata reason)
        external
        onlyRole(BRIDGE_OPERATOR_ROLE)
        whenNotPaused
    {
        if (!bridgedCredentials[wallet].isActive) revert NotBridged();

        bridgedCredentials[wallet].isActive = false;
        totalBridged--;

        emit BridgedCredentialRevoked(wallet, reason, block.timestamp);
    }

    // ═══════════════════════════════════════════════════════════════════════
    //  ADMIN FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════

    function addChain(uint256 chainId, string calldata name)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        _addChain(chainId, name);
    }

    function removeChain(uint256 chainId)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        isChainSupported[chainId] = false;
        delete supportedChains[chainId];
        emit ChainRemoved(chainId);
    }

    function setOracleSigner(address newSigner)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        if (newSigner == address(0)) revert InvalidAddress();
        emit OracleSignerUpdated(oracleSigner, newSigner);
        oracleSigner = newSigner;
    }

    function setSybilNet(address _sybilNet)
        external
        onlyRole(DEFAULT_ADMIN_ROLE)
    {
        if (_sybilNet == address(0)) revert InvalidAddress();
        sybilNet = ISybilNet(_sybilNet);
    }

    function pause()   external onlyRole(DEFAULT_ADMIN_ROLE) { _pause(); }
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) { _unpause(); }

    // ═══════════════════════════════════════════════════════════════════════
    //  VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Returns true if the wallet has an active bridged credential.
    function isBridgedHuman(address wallet) external view returns (bool) {
        return bridgedCredentials[wallet].isActive;
    }

    /// @notice Returns the full bridged credential struct.
    function getBridgedCredential(address wallet)
        external
        view
        returns (BridgedCredential memory)
    {
        return bridgedCredentials[wallet];
    }

    /// @notice Returns the lock record for a wallet on the source chain.
    function getLockRecord(address wallet)
        external
        view
        returns (LockRecord memory)
    {
        return lockRecords[wallet];
    }

    /// @notice Check if a credential is currently locked for bridging.
    function isCredentialLocked(address wallet) external view returns (bool) {
        return lockRecords[wallet].isLocked;
    }

    // ─── Internal ─────────────────────────────────────────────────────────

    function _addChain(uint256 chainId, string memory name) internal {
        supportedChains[chainId] = name;
        isChainSupported[chainId] = true;
        emit ChainAdded(chainId, name);
    }
}

contracts/ZKVerifier.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

/**
 * @title ZKVerifier
 * @notice Verifies Groth16 zk-SNARK proofs of humanity.
 *         Protects against proof replay attacks using a nullifier.
 */
contract ZKVerifier {

    // Proof replay protection
    // To be perfectly anonymous, we might use a hash of the proof itself,
    // or a specific nullifier output from the circuit. 
    // Here we will use a hash of the proof parameters as the nullifier for simplicity.
    mapping(bytes32 => bool) public proofNullifiers;

    event ProofVerified(address indexed submitter, uint256 commitment, uint256 timestamp);

    error ProofAlreadyUsed();
    error InvalidProof();

    /**
     * @notice Verifies a Groth16 proof of humanity
     * @param pA Point A of the proof
     * @param pB Point B of the proof
     * @param pC Point C of the proof
     * @param pubSignals Public signals: [threshold, walletCommitment]
     * @return bool True if proof is valid
     */
    function verifyHumanityProof(
        uint[2] memory pA,
        uint[2][2] memory pB,
        uint[2] memory pC,
        uint[4] memory pubSignals // We pad this to 4 in case snarkjs expects it, or keep it generic
    ) public returns (bool) {

        // 1. Replay Protection
        // Generate a unique identifier for this proof
        bytes32 nullifier = keccak256(abi.encodePacked(pA, pB, pC, pubSignals));

        if (proofNullifiers[nullifier]) {
            revert ProofAlreadyUsed();
        }

        // 2. Verify the proof
        bool isValid = _verifyProof(pA, pB, pC, pubSignals);

        if (!isValid) {
            revert InvalidProof();
        }

        // 3. Mark proof as used
        proofNullifiers[nullifier] = true;

        // pubSignals[1] is typically the walletCommitment in our circuit
        // We emit it so the protocol knows which commitment was verified
        emit ProofVerified(msg.sender, pubSignals[1], block.timestamp);

        return true;
    }

    /**
     * @dev Internal stub for the actual snarkjs-exported verification logic.
     *      TODO: Replace this block with the actual snarkjs-exported verification key pairing check
     *      once the setup.sh script generates the final circuits.
     */
    function _verifyProof(
        uint[2] memory /* pA */,
        uint[2][2] memory /* pB */,
        uint[2] memory /* pC */,
        uint[4] memory /* pubSignals */
    ) internal pure returns (bool) {
        // Mock verification logic
        // In reality, this would use pairing precompiles (e.g., ecrecover, pairing)
        // For development/stub purposes, we accept all proofs unless a parameter is zero

        // Example mock check: 
        // if (pA[0] == 0) return false;

        return true; 
    }
}

